import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math3.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class OpenMapRealVector_unitize_TriageGen1Test {

    private static final double EPSILON = 1e-10;



    @Test
    public void testUnitize_SparseVector() {
        // Test with a sparse vector to ensure the iterator logic works correctly
        OpenMapRealVector vector = new OpenMapRealVector(10);
        vector.setEntry(2, 10.0);
        vector.setEntry(5, 10.0);

        // Norm = sqrt(10^2 + 10^2) = sqrt(200) = 10 * sqrt(2)
        double norm = Math.sqrt(200.0);

        vector.unitize();

        Assert.assertEquals(10.0 / norm, vector.getEntry(2), EPSILON);
        Assert.assertEquals(10.0 / norm, vector.getEntry(5), EPSILON);
        Assert.assertEquals(0.0, vector.getEntry(0), EPSILON);
        Assert.assertEquals(1.0, vector.getNorm(), EPSILON);
    }






}

